//! Ruby-made plates with two readers, and a Ruby own-tablet plate for the
//! notebook, read by the Rust port (fixtures generated by
//! tests/fixtures/gen_two_readers_fixtures.rb against the original library).

use std::collections::BTreeMap;

use rustergraphia::grille::{Grille, Part};
use rustergraphia::{notebook, two_readers, Value};

const KEY: &str = "K7Q2M-ZXB4P";

fn fixture(name: &str) -> String {
    let path = format!("{}/tests/fixtures/{name}", env!("CARGO_MANIFEST_DIR"));
    std::fs::read_to_string(path).unwrap()
}

fn abbot() -> Grille {
    Grille::new(KEY, Part::Whole).unwrap()
}

#[test]
fn ruby_game_plate_reads_for_both_readers() {
    let svg = fixture("two_readers_game.svg");
    let reading = two_readers::read(&svg, &abbot(), None).unwrap();
    assert_eq!(reading.message, "relics lie under the third pillar");
    assert_eq!(
        reading.decoy.as_deref(),
        Some("vespers at six in the choir")
    );
    assert_eq!(reading.reader, Part::Abbot);

    let novice = Grille::new(abbot().novice().code(), Part::Whole).unwrap();
    let reading = two_readers::read(&svg, &novice, None).unwrap();
    assert_eq!(reading.message, "vespers at six in the choir");
    assert_eq!(reading.decoy, None);
    assert_eq!(reading.reader, Part::Novice);
}

#[test]
fn ruby_sealed_plate_opens_with_the_passphrase_and_key() {
    let svg = fixture("two_readers_sealed.svg");
    let reading = two_readers::read(&svg, &abbot(), Some("monastery gate")).unwrap();
    assert_eq!(reading.message, "Les reliques sont à Cîteaux");
    assert_eq!(reading.decoy.as_deref(), Some("Vêpres à six heures"));
    assert_eq!(reading.reader, Part::Abbot);

    assert!(two_readers::read(&svg, &abbot(), Some("wrong passphrase")).is_err());
}

#[test]
fn notebook_matches_the_ruby_library_on_the_same_plate() {
    let svg = fixture("notebook_plate.svg");
    let expect: serde_json::Value = serde_json::from_str(&fixture("notebook_expect.json")).unwrap();

    let sequence = notebook::read(&svg).unwrap().expect("a way reads it");
    let want: Vec<Value> = expect["sequence"]
        .as_array()
        .unwrap()
        .iter()
        .map(|n| n.as_u64().unwrap() as Value)
        .collect();
    assert_eq!(sequence, want);

    let entries = notebook::entries(&sequence);
    let want = expect["entries"].as_array().unwrap();
    assert_eq!(entries.len(), want.len());
    for (entry, want) in entries.iter().zip(want) {
        assert_eq!(u64::from(entry.sum), want["sum"].as_u64().unwrap());
        assert_eq!(entry.seen as u64, want["seen"].as_u64().unwrap());
        let spellings: Vec<(Value, Value)> = want["spellings"]
            .as_array()
            .unwrap()
            .iter()
            .map(|pair| {
                let pair = pair.as_array().unwrap();
                (
                    pair[0].as_u64().unwrap() as Value,
                    pair[1].as_u64().unwrap() as Value,
                )
            })
            .collect();
        assert_eq!(entry.spellings, spellings);
    }

    let sums: Vec<Value> = entries.iter().map(|entry| entry.sum).collect();
    let tablet: BTreeMap<Value, char> = expect["tablet"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| {
            let row = row.as_array().unwrap();
            (
                row[0].as_u64().unwrap() as Value,
                row[1].as_str().unwrap().chars().next().unwrap(),
            )
        })
        .collect();
    let right = |taken: &[Value]| -> BTreeMap<Value, char> {
        taken.iter().map(|sum| (*sum, tablet[sum])).collect()
    };
    let held_pairs = |value: &serde_json::Value| -> Vec<(Value, char)> {
        value
            .as_array()
            .unwrap()
            .iter()
            .map(|row| {
                let row = row.as_array().unwrap();
                (
                    row[0].as_u64().unwrap() as Value,
                    row[1].as_str().unwrap().chars().next().unwrap(),
                )
            })
            .collect()
    };

    let held = notebook::held(&svg, &right(&sums[..3]), &[]).unwrap();
    assert_eq!(
        held.into_iter().collect::<Vec<_>>(),
        held_pairs(&expect["held_first3"])
    );
    let held = notebook::held(&svg, &right(&sums[..2]), &[]).unwrap();
    assert_eq!(
        held.into_iter().collect::<Vec<_>>(),
        held_pairs(&expect["held_first2"])
    );
    let last2 = &sums[sums.len() - 2..];
    let inked = &sums[..sums.len() - 2];
    let held = notebook::held(&svg, &right(last2), inked).unwrap();
    assert_eq!(
        held.into_iter().collect::<Vec<_>>(),
        held_pairs(&expect["held_last2_inked"])
    );
}
